<?php
$u=user();$b=json_body();require_fields($b,['purpose','fileName','contentType','dataUri']);$purposes=['profile-photo','professional-photo','driver-service-photo','guide-service-photo','professional-cover','professional-gallery','professional-document','vehicle-photo','vehicle-document'];if(!in_array($b['purpose'],$purposes,true))fail(422,'VALIDATION_ERROR','The request contains invalid data.',['purpose'=>['Unsupported upload purpose.']]);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(in_array($b['purpose'],['professional-document','vehicle-document'],true))$allowed['application/pdf']='pdf';$type=(string)$b['contentType'];if(in_array($b['purpose'],['professional-document','vehicle-document'],true)&&$type==='image/webp')fail(415,'UNSUPPORTED_MEDIA_TYPE','Documents accept PDF, JPG or PNG.');if(!isset($allowed[$type]))fail(415,'UNSUPPORTED_MEDIA_TYPE','Only JPEG, PNG and WebP images are allowed.');if(!preg_match('#^data:'.preg_quote($type,'#').';base64,(.+)$#s',(string)$b['dataUri'],$m))fail(422,'VALIDATION_ERROR','The dataUri is invalid.',['dataUri'=>['Expected a complete base64 data URI.']]);$bytes=base64_decode($m[1],true);if($bytes===false)fail(422,'VALIDATION_ERROR','The image encoding is invalid.');if(strlen($bytes)>5*1024*1024)fail(413,'UPLOAD_TOO_LARGE','The maximum decoded size is 5 MiB.');$finfo=new finfo(FILEINFO_MIME_TYPE);if($finfo->buffer($bytes)!==$type)fail(415,'UNSUPPORTED_MEDIA_TYPE','The file signature does not match its declared type.');$id=uuid();$private=in_array($b['purpose'],['professional-document','vehicle-document'],true);$dir=($private?partner_private_storage_root():upload_storage_root()).'/'.$u['id'];if(!is_dir($dir)&&!mkdir($dir,0700,true)&&!is_dir($dir))fail(500,'UPLOAD_FAILED','Could not create persistent upload storage.');$name=$id.'.'.$allowed[$type];if(in_array($b['purpose'],['professional-document','vehicle-document'],true)){if(preg_match('/[^a-zA-Z0-9_. -]/',(string)$b['fileName'])||strlen($b['fileName'])>180)fail(422,'VALIDATION_ERROR','Use a simple file name.');}if(file_put_contents($dir.'/'.$name,$bytes)===false)fail(500,'UPLOAD_FAILED','Could not store the upload.');if($private)chmod($dir.'/'.$name,0600);$path=($private?'private-documents/':'uploads/').$u['id'].'/'.$name;db()->prepare('INSERT INTO uploads(id,user_id,purpose,file_name,content_type,path,size_bytes) VALUES(?,?,?,?,?,?,?)')->execute([$id,$u['id'],$b['purpose'],$b['fileName'],$type,$path,strlen($bytes)]);out(['id'=>$id,'uploadId'=>$id,'purpose'=>$b['purpose'],'fileName'=>$b['fileName'],'contentType'=>$type,'sizeBytes'=>strlen($bytes),'url'=>upload_url($id),'createdAt'=>(new DateTimeImmutable())->format(DATE_ATOM)],201);
